"""Build fixed offline packet lessons, preserving the existing site shell."""
from pathlib import Path
from html import escape as e
import json, re
from packet_examples import examples

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs'
CASES=examples()
BY_ID={c['id']:c for c in CASES}
PAGES=[('packet-analysis','报文解析总览'),('packet-mms','MMS：从对象到请求与响应'),('packet-goose','GOOSE：从状态到二层事件帧'),('packet-sv','SV：从采样到 ASDU'),('packet-scd-mapping','SCD 与报文的双向映射'),('packet-cases','完整案例与分析练习'),('packet-capacity','一个报文能装多少信号')]

def write(path,text):path.write_text(text,encoding='utf-8')
def table(headers,rows):
    return '<div class="reference-table"><table><thead><tr>'+''.join('<th scope="col">'+e(str(v))+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,title,body):return '<section><h2 id="'+id+'">'+title+'</h2>'+body+'</section>'
def pre(text):return '<pre><code>'+e(text)+'</code></pre>'
def xml(text):return '<pre data-language="xml"><code>'+e(text)+'</code></pre>'
def widget(ids):
    case=BY_ID[ids[0]]
    raw='\n'.join(f'{i:04x}  '+' '.join(case['hex'].split()[i:i+16]) for i in range(0,case['size'],16))
    rows=[]
    for i,f in enumerate(case['fields']):
        rows.append('<tr><td><button type="button" data-field-index="'+str(i)+'">'+e(f['name'])+'</button></td><td>'+str(f['start'])+'…'+str(f['start']+f['length']-1)+'</td><td>'+str(f['length'])+'</td><td>'+e(f['dtype'])+'</td><td>'+e(f['value'] or '容器')+'</td><td>'+e(f['meaning'])+'</td><td>'+e(f['scd'])+'</td><td>'+e(f['ws'])+'</td></tr>')
    return '<div class="packet-workbench" data-cases="'+' '.join(ids)+'"><p class="packet-legend">'+e(case['note'])+' 偏移为从0开始的十进制；静态Hex左侧行号为十六进制。字段范围包含Tag/Length，详情另列头长。</p><div class="packet-static"><h3>'+e(case['label'])+'</h3>'+pre(raw)+'</div><details class="packet-field-table"><summary>展开完整逐字段对照表（'+e(case['label'])+'）</summary><div class="reference-table"><table><thead><tr><th>字段（可点击）</th><th>偏移</th><th>字节</th><th>数据类型</th><th>值</th><th>含义</th><th>SCD</th><th>Wireshark</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></details></div>'

BOUNDARY='<p class="notice">本模块使用原创、脱敏、固定教学案例。页面只在本地切换示例和高亮字节；不读取用户抓包、不发送报文。XML 为保留引用链的部分模型，不等同于完整可投产 SCD、设备手册或标准原文。能解释本例不等于完成独立现场分析能力或符合性验证。</p>'
SOURCES='''<p>版次与来源边界：以项目既有早期 IEC 61850-8-1 中文资料的传统 MMS/GOOSE 映射为起点，并参照公开解码器 ASN.1 定义核对结构；SV 采用明确声明的 9-2 八通道 INT32/Quality 教学布局。它不是跨版次唯一实现，也不宣称完整符合 9-2LE 或 IEC 61869-9。本地9-2为DL/T 860.92—2006扫描件，本次视觉复核PDF第16～17页（印刷第12～13页）表13/14的容器及基础类型；早期smpSynch为BOOLEAN，本例按较新版公开解码定义的0/1/2枚举解释，1表示local，不能混用。7-2扫描件未逐条核验。公开解码器是交叉核对资料，不能替代适用版次标准。</p>
<p>职责：IEC 61850-6 管配置与交换；7-2 定义 ACSI（Abstract Communication Service Interface，抽象通信服务接口）；7-3 定义 CDC（Common Data Class，公用数据类）；7-4 定义 LN（Logical Node，逻辑节点）及数据对象；8-1 将服务映射到 MMS/传统 GOOSE；9-2 定义 SV 以太网映射。ISO 9506 定义 MMS（Manufacturing Message Specification，制造报文规范）；ASN.1（Abstract Syntax Notation One）描述结构；BER（Basic Encoding Rules）将结构编码为字节。IEC 62351 安全扩展不在本例内。</p>
<p>可选在线追溯（离线阅读不依赖链接）：<a href="https://webstore.iec.ch/en/publication/6028">IEC 标准体系目录</a> · <a href="https://www.itu.int/rec/T-REC-X.690-202102-I/en">ITU-T X.690 BER 规则</a> · <a href="https://raw.githubusercontent.com/wireshark/wireshark/master/epan/dissectors/asn1/mms/mms.asn">Wireshark MMS ASN.1</a> · <a href="https://raw.githubusercontent.com/wireshark/wireshark/master/epan/dissectors/asn1/goose/goose.asn">GOOSE ASN.1</a> · <a href="https://raw.githubusercontent.com/wireshark/wireshark/master/epan/dissectors/asn1/sv/sv.asn">SV ASN.1</a>。</p><p>显示字段名按公开 Wireshark 参考核对：<a href="https://www.wireshark.org/docs/dfref/m/mms.html">MMS</a> · <a href="https://www.wireshark.org/docs/dfref/g/goose.html">GOOSE</a> · <a href="https://www.wireshark.org/docs/dfref/s/sv.html">SV</a>。具体版本、偏好、上下文可能改变节点名或是否解码；本模块未调用 Wireshark 引擎解码这些合成帧。</p>'''

overview=section('scope','1. 先回答：为什么以 MMS、GOOSE、SV 为主线？','''<p>在常见变电站工程中，以三类核心业务通信学习报文是合理的。IEC 61850 是覆盖模型、服务、工程配置与映射的标准体系；MMS、GOOSE、SV 是其中常见通信主线，不能代替整个体系。本文限定传统站内以太网映射，不把其他场景强行归入这三类。</p>'''+table(['主线','解决的问题 / 原创场景','承载与交互','先找什么'],[
('MMS','监控客户端读取开关位置、接收遥信/遥测报告；控制和定值的服务映射','TCP/IP上ISO关联；请求/响应和未确认报告','同一关联、服务、invokeID、domain/item名'),('GOOSE','IED向订阅端发布开关状态、保护事件或联闭锁信息','传统8-1为Ethernet二层组播，无TCP确认；用重传维持状态','0x88B8、gocbRef、datSet、stNum/sqNum'),('SV / SMV','合并单元向保护/测控提供电流、电压瞬时采样','传统9-2为Ethernet二层发布；按配置周期连续采样','0x88BA、svID、ASDU、smpCnt、seqData')])+'''<p>GOOSE = Generic Object Oriented Substation Event（面向通用对象的变电站事件）；SV = Sampled Values（采样值），SCL 中常用 SMV 命名。应用场景可能重叠：位置既能由 MMS 读/报告，也能被配置为 GOOSE；瞬时采样 SV 与 MMS 的 RMS/相量遥测不可混同。</p><p>还要了解 Ethernet、可选 802.1Q VLAN、ARP、IPv4/IPv6、TCP 分段重组、TPKT/COTP、关联协商、ASN.1/BER、时间品质和 SNTP/PTP、PRP/HSR 冗余及捕获截断。IEC 61850-8-2、可路由事件/采样映射等属于进一步范围；抓到其他流量不能一概当作异常。</p>''')
overview+=section('prerequisites','2. 现有网页读完后，基础够不够？','''<p>足够进入本模块的模型与配置学习；尚不足以仅凭报文字节独立解释工程业务。现有材料已经具备以下前置链，本模块补上编码、关联、顺序和反查练习。</p>'''+table(['已具备','前置页面','仍需补充'],[
('IED→LD→LN→DO/DA、CDC、FC','IED与数据模型；对象引用；数据属性取值','实例与类型链对齐，MMS名字的domain/item拆解'),('FCDA与控制块引用、工程文件类型','SCD十分钟；工具箱；控制块参考','字段能否在帧中出现、FCDA顺序与真实编码'),('ACSI与MMS/GOOSE/SV映射','ACSI服务；service-mapping；通信与过程层','Read完整请求/响应、BER长度、帧与PDU边界'),('品质、时间、重传与工程证据边界','测量链；开发数据契约','Dbpos位串、SV品质容器、状态与重传计数差异')])+'''<p>按顺序复习：<a href="ied-data-model.html">IED 与模型</a> → <a href="object-reference.html">对象引用</a> → <a href="scd-in-ten-minutes.html">SCD 十分钟</a> → <a href="scd-reading-toolbox.html">引用追踪</a> → <a href="control-blocks-reference.html">DataSet / Control Block</a> → <a href="acsi-services.html">ACSI 服务</a> → <a href="service-mapping.html">映射</a>；品质时间不清楚时返回 <a href="measurement-chain.html">测量链</a>、<a href="cdc-common-types.html">公用属性类型</a>。</p>''')
overview+=section('method','3. 固定的六步分析法','''<ol><li>确定用途：一次物理量/状态是什么，谁发布、谁消费，当前证据能说明什么。</li><li>找配置：IED / AP / LD / LN / DO / DA，沿类型模板确认 FC、基本类型、单位。</li><li>找集合与控制：GOOSE/SV 看 DataSet 和控制块；MMS 单变量 Read 可直接访问，报告再看 RCB / DataSet。</li><li>读结构：先帧长与协议层，再服务/APDU/ASDU，按 Tag/Length 确定 Value 边界。</li><li>还原值：按 FCDA 顺序和类型解释，记录品质、时标、计数、配置版本和歧义。</li><li>反查与变化：回到 SCD 验证发布源/订阅证据，比较事件与重传、采样相邻时刻；证据不足保留未知。</li></ol><p class="packet-path">SCD → IED / AP → LD / LN → DO / DA → DataSet / Control Block → Communication → 报文 → 字段 → 信号；MMS 的直接 Read 在 DO/DA 后进入变量访问服务，不必绕过一个控制块。</p>''')
overview+=section('map','4. 进入教程与内置案例','<div class="component-grid">'+''.join('<a href="'+stem+'.html"><b>'+title+'</b><span>'+desc+'</span></a>' for (stem,title),desc in zip(PAGES[1:],['Read Request → Read Response → Dbpos','分位 → 合位 → 相同状态重传','八通道、16个FCDA、1/2个ASDU','正向链、反向证据、歧义处理','完整Hex、解题步骤、可展开答案','理论/协议/网络/设备约束与可计算例子']))+'</div>'+BOUNDARY)
overview+=section('ber','5. 从 Hex 到字段，先认识长度','''<p><code>84 02 06 80</code> 在本例 MMS Data / GOOSE Data 上下文中是 BIT STRING：Tag=84，Length=02（Value占2字节），Value=06 80。06 表示末字节6个未用位，有效位10表示 Dbpos on。它不能被解读为整数0x0680，也不能脱离上下文把所有84都叫位串：GOOSE顶层84是时间字段。</p><p>BER 短长度 7F 表示127；长长度 81 80 表示后续1字节给出128；82 01 00 表示256。父容器长度只统计其Value，子字段的Tag/Length也在父Value内。长度阈值变化会让后续偏移整体移动，因此禁止把示例偏移当成通用解析规则。</p><p>层次名：PDU = Protocol Data Unit；APDU = Application Protocol Data Unit；ASDU = Application Service Data Unit。SV 的 seqData 是八位串，通道值不各带一个 BER Tag；MMS/GOOSE 的 Data 选择则包含类型标签。</p>''')

mms_content=section('use','A. 这个报文是干什么的？','''<p>值班画面需要显示断路器当前分合位，客户端可以 Read 读取状态；持续遥信/遥测通常配置报告。MMS 承载 IEC 61850 客户端/服务器服务映射，不能把 MMS 等同于轮询，也不能把一次 Write 成功等同于断路器已经动作。</p><p><b>Service 是协议操作及其参数/结果约定。</b>例如 Read 定义“访问哪些变量”和“每项返回值或错误”；Confirmed Request 中的服务选择 CHOICE 标签决定操作，Confirmed Response 给出对应结果。它不是可以随意填写的普通业务字段。invokeID 只在同一应用关联中配对请求与响应，不能跨连接全局匹配。</p>''')
mms_content+=section('source','B. 从 SCD 对象到 MMS Variable','''<p>本例：IED=Demo，AP=AP1，LDevice@inst=LD0，无显式 ldName，因此示例 LDName=DemoLD0；LN=XCBR1；DO=Pos（DPC）；DA=stVal，FC=ST，bType=Dbpos。模型中“合位”编码2，映射到两个有效位10。</p>'''+pre('SCD Demo / AP1 / LD0 / XCBR1 / Pos / stVal [ST]\n→ MMS domainID = DemoLD0\n→ MMS itemID   = XCBR1$ST$Pos$stVal\n→ Read Request invokeID=1\n→ Read Response invokeID=1, AccessResult.success = BIT STRING 10 (on)')+'''<p>名称不是把任意工程字符串机械替换成“$”：先确定 LDName、完整 LNName（prefix+lnClass+inst）、FC 与属性结构。本例模型还把 stVal/q 放入 dsPos，供报告或 GOOSE 使用，但本例单变量 Read 不依赖它们。完整结构见 <a href="packet-scd-mapping.html#model">类型与 SCD</a>。</p>''')
mms_content+=section('structure','C. 整体层次与常见服务','''<p>数据阶段层级：Ethernet（本例14字节）→ IPv4（20字节，实际按IHL）→ TCP（20字节，实际按DataOffset）→ TPKT（4字节，包含总长度）→ COTP DT（本例3字节）→ Session DATA（本例4字节）→ Presentation / PDV-list → MMS。建关联另有 ACSE AARQ/AARE、MMS Initiate；ACSE 不会在每一个 Read 帧重复出现。</p><p>本例假定已协商 MMS presentation-context-identifier=3，且每帧恰含一个完整TPKT。真实TCP可将一个TPKT切到多段、将多个TPKT合并；先做流重组再看MMS，不按抓包帧边界猜PDU边界。TCP/102只是一条筛选线索，未完成上下文验证不能认定都是MMS。</p>'''+table(['交互 / 服务','在IEC 61850中的作用','报文与注意点'],[
('Initiate Request / Response','协商MMS最大PDU、并发未完成服务、服务支持等','A8/A9 PDU；关联建立阶段，需要与ACSE/表示上下文一并检查'),('GetNameList','发现域/命名对象/列表的目录','Confirmed服务[1]；目录不是当前值，也不是SCD文件传输'),('Read','读DO/DA、控制块或命名变量列表','Confirmed服务[4]；VariableAccessSpecification选择变量列表或列表名'),('Write','写可写数据、RCB属性、定值或控制结构','Confirmed服务[5]；权限/FC/状态机和逐项错误仍有效'),('Report','缓冲/非缓冲报告由服务器主动发出','Unconfirmed PDU → InformationReport，无invokeID；看RptID、OptFlds、inclusion-bitstring、值与ReasonForInclusion'),('Control','选择、操作、取消和结果语义','ACSI Control不是一个名为Control的MMS服务；SBO读，SBOw/Oper/Cancel写；CommandTermination另核对'),('Confirmed Error / Reject','服务失败或PDU处理拒绝','与ReadResponse内每项AccessResult.failure不同；不能把三者混为一类')])+'''<p>报告链：ReportControl → DataSet → 触发项 dchg/qchg/dupd/GI/周期等 → 使能后的运行时 RCB → InformationReport。inclusion-bitstring 选择本次包含的成员，不能假定每次总含全部信号；可选数据引用/配置版本按 OptFlds；报告分段还要看分段相关字段。SCD 不保存客户端实际使能状态。</p>''')
mms_content+=section('hex','D. Wireshark 中如何拆解：完整 Read Request','''<p>筛选 <code>mms</code> 或 <code>tcp.port == 102</code>，确认关联后展开 confirmed-RequestPDU → invokeID → read → variableAccessSpecification → listOfVariable → name → domain-specific。显示过滤字段名按版本核对；本页详情中的标签与偏移能直接回指原始Hex。</p>'''+widget(['mms-read']))
mms_content+=section('response','D. 配对完整 Read Response','''<p>同一关联中 invokeID=1，对应一个访问结果。请求未要求 specificationWithResult，因此此响应不重复对象名；按请求变量顺序解释。成功值直接取 MMS Data 的 BIT STRING 标签，失败分支使用 DataAccessError。只读 stVal 的本例响应不包含 q/t，不应从值“2”推断品质或新鲜度。</p>'''+widget(['mms-response']))
mms_content+=section('organize','E. 某个状态或测量值怎样进入数据区？','''<ol><li>从 XCBR1.Pos.stVal 出发，沿 LNodeType → DOType 确认 DPC/Dbpos、ST、只读状态含义。</li><li>将访问对象映射为 domain/item，Read Request 只携带访问规格，不携带“想读到的值”。</li><li>服务端应用更新模型，编码 Read Response 的 AccessResult；分位位串为84 02 06 40，合位为84 02 06 80。若响应品质或时间也需要，须显式访问对应属性/结构。</li><li>改成报告时才沿 dsPos 成员顺序、brcbPos、OptFlds、inclusion-bitstring 组织 InformationReport；不能套用ReadResponse字节。</li><li>测量 FLOAT32 不是把十进制文本贴进报文：典型MMS浮点值1.0示意为87 05 08 3f 80 00 00（08是指数宽度，后4字节IEEE754）；单位/比例和原始/二次/一次值仍由模型决定。</li></ol><p>客户端要控制断路器时访问适用的CO结构，按ctlModel、origin、ctlNum、T、Check、Test等规则完成选择/操作及结果确认。状态stVal是反馈，不是用普通Write改成“合位”的命令接口。继续阅读 <a href="control-input-models.html">控制模型</a>、<a href="setting-group-development.html">定值开发流程</a>。</p>''')

goose_content=section('use','A. 这个报文是干什么的？','''<p>断路器位置变化后，发布IED把数据集状态提供给订阅IED用于联闭锁或状态交换。传统 GOOSE 直接使用Ethernet组播，EtherType=0x88B8，无IP/TCP、无逐接收端ACK；快速重传与稳定期重传帮助订阅端维持当前状态。报文到达不能单独证明出口逻辑或开关动作。</p>''')
goose_content+=section('source','B. 从 XCBR.Pos 到 DataSet 与 GoCB','''<p>读取 <a href="../data/packet-demo.scd">本地原创部分 SCD</a>：Demo/AP1/LD0/LN0/DataSet dsPos 第1个FCDA是 XCBR1.Pos.stVal [ST]（Dbpos），第2个是 Pos.q [ST]（Quality）；GSEControl gcbPos 引用 dsPos，confRev=1。GoCB 是运行时 GOOSE Control Block，SCL 的 GSEControl 是其配置声明。</p>'''+xml('<DataSet name="dsPos">\n  <FCDA ldInst="LD0" lnClass="XCBR" lnInst="1" doName="Pos" daName="stVal" fc="ST"/>\n  <FCDA ldInst="LD0" lnClass="XCBR" lnInst="1" doName="Pos" daName="q" fc="ST"/>\n</DataSet>')+'''<p>网络侧 ConnectedAP@iedName=Demo、apName=AP1 → GSE@ldInst=LD0、cbName=gcbPos；Address给出目的MAC和数值APPID=0x1001。GSEControl@appID="DemoPos"是应用标识字符串，本例对应goID；它与Address/P[@type="APPID"]的16位数值不同。没有配置VLAN的本例以14字节Ethernet头演示，带单层802.1Q时业务头通常后移4字节，不能固定用本例偏移解所有帧。</p>''')
goose_content+=section('structure','C. 报文如何组成？','''<p>Ethernet目的/源MAC各6字节、EtherType2字节 → GOOSE固定头（APPID、Length、Reserved1、Reserved2各2字节）→ GOOSE APDU（Tag 61，BER长度与字段）。Length=8+APDU长度，不包含MAC头、VLAN、FCS或Ethernet填充。线上的最小帧填充不应计入APDU。</p>'''+table(['字段','类型/长度（Value）','变化条件或含义'],[
('gocbRef / datSet / goID','VisibleString，变长','控制块引用 / 数据集引用 / 发布应用标识；不因每次重传改变'),('timeAllowedToLive','BER INTEGER，变长，毫秒','订阅端可等待下一帧的时间；可随重传阶段变化'),('t / timestamp','8字节UtcTime','本次状态变更时间；不是每一重传帧的新发送时间'),('stNum / sqNum','BER INTEGER，变长','状态序号 / 同状态发送序号；新事件sqNum重置为0；回绕与重启不能简单当丢帧'),('test（早期基线）','BOOLEAN，通常1字节','历史8-1标签[7]；新解码器可显示simulation；与成员q.test及扩展头S位分别核对'),('confRev / ndsCom','INTEGER / BOOLEAN','配置修订 / 需要配置指示；数据集成员重排是需复核修订的情况，运行值变化不是配置变更'),('numDatSetEntries','BER INTEGER','本例为2，数FCDA顶层成员，不数allData结构内叶子'),('allData','SEQUENCE OF Data，变长','按DataSet声明顺序编码；成员可为基本值、结构或数组')])+'''<p class="caution">XCBR.Pos 是 DPC 双点位置。0=intermediate-state，1=off（本例分位），2=on（合位），3=bad-state。不要用BOOLEAN示范这个stVal；若用布尔保护动作信号，应换用已核对的SPS/ACT等具体模型成员。</p>''')
goose_content+=section('hex','D. Hex、字段与信号变化联动','''<p>从下拉框依次选择分位、合位新事件、重传；橙色底线指出相对上一次所选帧变化的字节，蓝色表示当前字段范围。列表还可按层筛选，点击Hex会反查包含该字节的最小字段。</p>'''+widget(['goose-open','goose-close','goose-retransmit'])+table(['阶段','stNum','sqNum','t','allData第1项','允许等待时间'],[('分位稳定帧',7,4,'UTC秒0x65000000','84 02 06 40 → 01/off','1000ms'),('合位新事件首帧',8,0,'UTC秒0x65000001','84 02 06 80 → 10/on','20ms'),('合位后续重传',8,1,'保持0x65000001','保持84 02 06 80','40ms')])+'''<p>时标格式：4字节UTC秒、3字节二进制秒小数（分母2^24）、1字节时间品质。本例秒小数为0，品质8A仅声明本教学值，不代表实测精度。Pos.q是成员品质，GOOSE顶层t的最后字节是时间品质，两者不是同一对象。</p>''')
goose_content+=section('organize','E. 从状态到教学报文，而非修改几个字节','''<ol><li>应用层获得位置变化和品质，按模型更新Pos.stVal/q/t；本例dsPos只选择stVal/q，未选择Pos.t。</li><li>按两个FCDA确定Dbpos与Quality。Dbpos的BER位串Value首字节06表示6个未用位；Quality取13有效位，Value为03 00 00。若选择整个FCD，allData应按结构编码，不能继续套用两项标量布局。</li><li>GoCB观察数据集的新状态，本例stNum 7→8、sqNum→0、顶层t变为新事件时间；成员q保持原值，confRev仍为1。</li><li>重传保持数据、stNum和事件t，sqNum增长；具体时间曲线由配置与实现决定。20/40ms是本例声明的示意，不是标准唯一时序或设备参数推荐。</li><li>按映射重新计算BER父长度、GOOSE Length及帧封装。长度跨127/255等阈值、序号增长时可能改变字节数与偏移，不能只定位一个值字节修改。</li></ol><p>MinTime/MaxTime是配置线索，不足以独立还原每次发送时刻；订阅需看Inputs/ExtRef、接收能力和现场验证，参见 <a href="packet-scd-mapping.html#reverse">反向映射</a>。</p>''')

sv_content=section('use','A. 这个报文是干什么的？','''<p>合并单元持续发布某时刻的电流/电压样本，接收端再用于保护、测量或计算。SV承载瞬时采样，不等于MMS遥测的有效值/相量。传统9-2直接映射Ethernet，EtherType=0x88BA；无TCP确认，也没有GOOSE的stNum/sqNum事件重传语义。</p>''')
sv_content+=section('source','B. 从电流、电压模型到采样数据集','''<p>本例Demo/SV0：TCTR1～4的Amp.instMag.i/q，TVTR1～4的Vol.instMag.i/q。人工声明通道顺序 IA、IB、IC、IN、UA、UB、UC、UN；每个通道由一个INT32样本和一个Quality组成，共16个FCDA。相别与中性通道来自本例契约，不能由TCTR实例号或svID猜测现场业务。</p><p>LN0/DataSet dsSV → SampledValueControl smv01（smvID=DemoSV1，confRev=1，nofASDU=1）→ ConnectedAP Demo/AP1 → SMV ldInst=SV0 cbName=smv01 → 目的MAC 01-0C-CD-04-00-01、APPID 0x4001。SmvOpts.dataSet=false，所以本例ASDU不含datSet字符串；仍需由控制块找到dsSV。</p><p>本例约定电流每计数0.001 A、电压每计数0.01 V，均是二次瞬时量；一次值还需已核对变比。八通道、50Hz每周波80样本的教学背景仅说明smpRate=80，不能据此宣称所有SV均为4000样本/秒、八通道或同样比例。本部分SCD没有完整保存比例/量纲/时钟配置，必须连同本页契约阅读。</p>''')
sv_content+=section('structure','C. 从 SV APDU 到一个或多个 ASDU','''<p>Ethernet → 8字节APPID/Length/Reserved头 → SV APDU / SavPdu（Tag 60）→ noASDU（Tag80）→ seqASDU（TagA2）→ ASDU（Tag30，可重复）→ 字段和sequence of Data（Tag87，Wireshark称seqData）。外层BER有类型与长度，seqData内的通道按已约定的宽度和字节序读取。</p>'''+table(['ASDU字段','本例Value长度','含义与变化'],[('svID','7字节字符串','流标识DemoSV1；不是通道名表'),('datSet','本例不发送','可选；有无由映射版次、选项决定'),('smpCnt','2字节','本例1000；相邻样本1001。回绕基准按采样模式/配置文件核对'),('confRev','4字节','配置修订1；不是每采一个样本就加一'),('refrTm / smpRate / smpMod','本例不发送','时间参考、采样率、采样模式等选项/版次内容；不能因缺字段就判坏帧'),('smpSynch','1字节','本例1/local；不同版次/配置文件需核对，同步标识不证明绝对精度'),('sequence of Data / seqData','64字节','8×(4字节有符号INT32+4字节Quality)。不含每个通道的名字、单位或BER Tag')])+'''<p>一个ASDU是一组采样数据，多个ASDU可聚合到同一帧。切换下面的两ASDU示例时，noASDU=2，长度及BER长长度随之变化；配置对照应换用 <a href="../data/packet-demo-two-asdu.scd">nofASDU=2的部分SCD变体</a>。两个ASDU都保留八通道布局，不能说成通道数翻倍。</p>''')
sv_content+=section('hex','D. 完整八通道 SV 与多 ASDU 对照',widget(['sv-one','sv-two'])+table(['通道','本例INT32','大端Hex','按声明比例得到的二次瞬时值'],[(ch,v, v.to_bytes(4,'big',signed=True).hex(' '),str(v*(.001 if i<4 else .01))+(' A' if i<4 else ' V')) for i,(ch,v) in enumerate(zip(['IA','IB','IC','IN','UA','UB','UC','UN'],[1000,-500,-500,0,100000,-50000,-50000,0]))])+'''<p>负数按32位二进制补码读取，不能当成无符号巨大正数。每个Quality占4字节，本例均00 00 00 00，表示有效位清零的教学品质。有效性、detailQuality、source、test、operatorBlocked等位及保留位需按适用9-2映射核对；未展示故障位组合不等于真实装置始终good。SV的4字节品质容器不能照搬GOOSE的84 03 03 00 00。</p>''')
sv_content+=section('quality','品质容器：先确认位编号约定','''<p>本例Quality按32位大端容器读取。下面使用编程常见的最低有效位LSB=0编号，适用标准表格可能从最高有效位编号，不能直接抄位号。validity位[1:0]，detailQuality位2～9，source位10，test位11，operatorBlocked位12；derived等扩展须按配置文件另核对。本例所有位为0。以test位单独置1的结构演算为例，整数掩码0x00000800对应字节00 00 08 00；它与GOOSE中按ASN.1位串编号组织q.test的位置不同。</p><p>交叉核对：<a href="https://raw.githubusercontent.com/wireshark/wireshark/master/epan/dissectors/packet-sv.c">Wireshark SV解码器的品质掩码和位编号说明</a>。本页未把解码器实现当成跨版次规范；现场应核对适用9-2/配置文件。</p>''')
sv_content+=section('organize','E. 电流样本如何进入报文？','''<ol><li>物理IA取样后由应用得到二次瞬时值，本例1.000A → 按契约0.001A/计数得到1000；这一步是量纲/比例契约，不是BER自动推导。</li><li>dsSV第1个FCDA为TCTR1.Amp.instMag.i，沿DemoSAV→DemoAnalogue确定INT32；第2个是对应q。seqData中先00 00 03 e8，再00 00 00 00，后续通道依声明顺序。</li><li>采样时刻前进时，样本值可能改变，smpCnt按配置节奏递增；confRev/svID保持，smpSynch随同步状态而非波形幅值改变。</li><li>多个ASDU各自携带计数与数据；本例1000/1001的值恰好相同，只演示容器与时刻，不将其说成有变化的波形。</li><li>按ASDU数重算seqASDU、SavPdu和固定头Length，核对网络预算和接收能力。固定八通道约定、比例及同步方案均需先于现场解释确认。</li></ol><p>抓包中看不到通道名或datSet时，保持“第N个样本字段”这一事实直到配置唯一匹配。进一步阅读 <a href="measurement-chain.html">采样与测量链</a>、<a href="packet-scd-mapping.html">SCD反查</a>。</p>''')

def mapping_demo():
    steps=[('SCD / 实例','Demo/AP1 → LDevice LD0 → XCBR1.Pos.stVal；实例lnType=DemoXCBR → DO Pos type=DemoDPC → DA stVal bType=Dbpos, fc=ST。'),('DataSet','LN0/DataSet@name=dsPos，FCDA[1]=Pos.stVal，FCDA[2]=Pos.q。这里2个标量成员；若删daName改FCD必须重新展开类型。'),('Control Block','LN0/GSEControl@name=gcbPos, datSet=dsPos, confRev=1, appID=DemoPos；运行时GoCB引用DemoLD0/LLN0$GO$gcbPos。'),('Communication','ConnectedAP iedName=Demo apName=AP1 → GSE ldInst=LD0 cbName=gcbPos → Address APPID=1001(十六进制)、目的MAC。'),('报文字段','gocbRef=DemoLD0/LLN0$GO$gcbPos，datSet=DemoLD0/LLN0$dsPos，goID=DemoPos，APPID=0x1001，allData[1]=84 02 06 80(合位)。'),('反查信号','用发布身份与引用定位唯一控制块，再取dsPos顺序和DemoDPC类型，才能将allData第1项称为本例XCBR1.Pos.stVal。订阅方业务还需Inputs/ExtRef和内部逻辑证据。')]
    return '<div data-mapping>'+''.join('<p class="mapping-detail" data-label="'+label+'"><b>'+label+'：</b>'+text+'</p>' for label,text in steps)+'</div>'

mapping_content=section('model','1. 共同的原创配置与类型链','''<p>案例文件 <a href="../data/packet-demo.scd">packet-demo.scd</a> 是保留实例、类型、数据集、控制块和Communication的原创部分模型；XML可读取，但省略标准必选公共对象、完整网络/授时与能力声明等，不作为XSD合格工程。本例所有IED/IP/MAC均人工编写；未读取真实工程来推断业务。</p>'''+pre('Demo / AP1 / LD0 / XCBR1 [lnType=DemoXCBR]\n  LNodeType DemoXCBR → DO Pos [type=DemoDPC]\n  DOType DemoDPC [cdc=DPC]\n    stVal: Dbpos, FC=ST → GOOSE/MMS BIT STRING 2有效位\n    q: Quality, FC=ST → GOOSE BIT STRING 13有效位\nDemo / AP1 / SV0 / TCTR1 [lnType=DemoTCTR]\n  DO Amp [type=DemoSAV, cdc=SAV]\n    instMag: Struct, FC=MX → DAType DemoAnalogue / i: INT32\n    q: Quality, FC=MX → SV 4字节映射容器')+'''<p>IED名不是一定等于MMS域名。常规LDName由IED名和ldInst形成，显式LDevice@ldName等情况按适用版本/模型核对。prefixed LN、SDO、BDA、数组或整个FCD都需沿类型展开；本例只演示无数组的明示标量路径。</p>''')
mapping_content+=section('forward','2. GOOSE 正向映射：逐步点击证据链',mapping_demo()+xml('<GSEControl name="gcbPos" type="GOOSE" appID="DemoPos" datSet="dsPos" confRev="1"/>')+'''<p>控制块的同名匹配要带上IED/AP/LD/LN作用域，不能只搜索字符串gcbPos。GSE@cbName指控制块名，GSE@ldInst指其所属LD；datSet是发布LN作用域中的数据集名，不是Communication路径。</p>''')
mapping_content+=section('sv-forward','3. SV 正向映射：不能在每帧找到所有配置','''<p>Demo/AP1/SV0/LLN0/DataSet dsSV（16 FCDA）→ SampledValueControl smv01 → SMV ldInst=SV0 cbName=smv01 → APPID=4001与目的MAC → 帧svID=DemoSV1、confRev=1、noASDU=1 → seqData按16个标量成员/八通道解释。datSet字符串与smpRate在此例没有发送，因此不能从Hex中凭空读出它们。</p>'''+xml('<SampledValueControl name="smv01" smvID="DemoSV1" datSet="dsSV" confRev="1" multicast="true" smpRate="80" nofASDU="1">\n  <SmvOpts refreshTime="false" sampleSynchronized="true" sampleRate="false" dataSet="false" security="false"/>\n</SampledValueControl>')+'''<p>nofASDU是每帧聚合数，不是DataSet成员数。SMV和SampledValueControl是两个不同配置位置；SmvOpts.dataSet是控制是否传输引用的选项，不能把不含datSet的流当成没有数据集。</p>''')
mapping_content+=section('mms-forward','4. MMS 对象映射与报告链的分支','''<p>直接读：DemoLD0/XCBR1.Pos.stVal [ST] → domain DemoLD0 / item XCBR1$ST$Pos$stVal → ReadRequest → invokeID=1同关联响应 → Dbpos=on。服务端AP/IP配置帮助定位连接，但运行时目录、协商与访问权限仍要查。</p><p>报告：同一dsPos还被ReportControl brcbPos引用 → 运行时BRCB与使能 → InformationReport。它不是gcbPos，也不因为数据集相同而自动发送GOOSE。必须查真实RptID、OptFlds、inclusion、confRev、分段与控制块状态；报告中的可选DataRef不是每帧必带。</p>''')
mapping_content+=section('reverse','5. 从 Wireshark 反查 SCD：匹配组合，而非猜名字',table(['观察事实','反查路径','还缺的证据'],[('GOOSE APPID1001 + gocbRef DemoLD0/LLN0$GO$gcbPos + datSet','Communication/ConnectedAP/GSE → IED/AP/LD/LN0/GSEControl → dsPos → FCDA与类型','检查MAC/VLAN、confRev和配置版本；接收Inputs/ExtRef与实际内部映射'),('SV APPID4001 + svID DemoSV1 + confRev1','SMV网络对象 → SampledValueControl smv01 → dsSV → 声明的值/q顺序','确认布局、比例、同步模式；没有datSet字符串时不能只凭APPID命名通道'),('MMS Read domain DemoLD0 + item XCBR1$ST$Pos$stVal','已确认服务器/AP → LDName → LN XCBR1 → FC ST → Pos.stVal → 类型','关联上下文、动态模型/目录及当前权限；响应按请求结果位置配对'),('InformationReport只含部分值','RptID/可选DataSet、DataRef/配置版本与inclusion → RCB/DataSet','运行时使能/触发、缓冲与分段；相同RptID候选需进一步消歧')])+'''<p>APPID只在其通信与工程上下文中帮助筛选，不能保证跨子网/多工程全局唯一。发现同名、重复APPID、不同confRev或SCD版本不明，应列出候选和冲突，暂停语义归属。源MAC可能因冗余/实现影响，不能反推厂家功能或跳闸对象。SCD描述预期，抓包描述观测，两者不一致时都不是自动的最终真相。</p>''')
mapping_content+=section('scd-fragment','6. 查看完整部分模型与下一个核对点','<details><summary>展开原创 SCL 部分模型（含全部16个SV成员与类型模板）</summary>'+xml((OUT/'data/packet-demo.scd').read_text(encoding='utf-8'))+'</details><p>本例未配置接收方Inputs/ExtRef，因此只能证明声明的发布链；不能证明任何接收端已经订阅、投运或使用这些值。配置完整性与现场业务链应回到 <a href="engineering-model-reading.html">工程证据检查</a>。</p>')

cases_content=section('cases','1. 三个完整案例，从字节回到对象','''<p>先在各协议页读解释，再在这里不看答案完成练习。完整数据帧均从目的MAC开始，到APDU结束，省略通常不在抓包文件中的前导码/SFD/FCS；MMS请求/响应是已建立关联的数据阶段，建链过程不属于本帧。</p>'''+table(['案例','起点','终点与对照'],[('MMS','XCBR1.Pos.stVal / Dbpos','请求对象 → 同关联invokeID1 → 响应位串10 → 合位'),('GOOSE','XCBR1.Pos由off到on，品质不变','两个dsPos成员 → gcbPos → allData、stNum、sqNum、t变化'),('SV','同一时刻8个二次瞬时样本','16个FCDA → smv01 → 一组ASDU内64字节seqData')]))
cases_content+=section('mms','2. MMS 完整请求 / 完整响应',widget(['mms-read'])+widget(['mms-response'])+'''<details class="self-check"><summary>练习：响应没有对象名，如何知道值属于谁？</summary><p>先证明同一TCP/应用关联，再按invokeID1匹配ReadRequest。请求只含一个变量，响应第1项对应DemoLD0/XCBR1.Pos.stVal。84 02 06 80的两个有效位是10，解释为Dbpos on；本例没有q/t，不能补推品质和发生时间。</p></details>''')
cases_content+=section('goose','3. GOOSE 完整事件与重传',widget(['goose-open','goose-close','goose-retransmit'])+'''<details class="self-check"><summary>练习：合位后第二帧为什么t不再改变？confRev为什么仍为1？</summary><p>该帧是同一数据集状态重传，sqNum由0到1，stNum保持8，t仍指向此状态事件。没有成员配置变更，所以本例confRev不随状态变化。第二个成员Quality未变；test、q.test与时间品质要分别解释。</p></details>''')
cases_content+=section('sv','4. SV 完整八通道采样帧',widget(['sv-one','sv-two'])+'''<details class="self-check"><summary>练习：16个FCDA是否意味着16路电流？如果seqData缺4字节怎么办？</summary><p>这里是8组值/q对，共16个标量FCDA，只能按契约称为IA～UN八通道。单ASDU应有64字节seqData；缺4字节先检查抓包截断、BER/头Length、配置布局和版本，不把后续品质错位当作下一相电流。两ASDU变体仍是八通道两个采样时刻，不是16个新通道。</p></details>''')
cases_content+=section('reverse-practice','5. 反向映射与未知情形','''<details class="self-check"><summary>给定APPID1001、gocbRef和allData第1项，列出反查步骤。</summary><p>先按当前子网/AP与GSE网络对象筛选，再用DemoLD0/LLN0$GO$gcbPos验证完整控制块引用及datSet，核对confRev和目的MAC。dsPos第1个FCDA是XCBR1.Pos.stVal，DemoDPC给出Dbpos类型，因此位串10解释为合位。未提供订阅方证据，不能声称闭锁了某个间隔。</p></details><details class="self-check"><summary>给定SV仅有APPID4001与64字节seqData，但没有相匹配SCD，能否命名IA？</summary><p>不能。长度可以支持某种布局假设，但不是业务证明。先记录svID、confRev、长度、ASDU/计数等事实，再取得版本匹配的控制块、数据集、类型、比例和同步约定。配置不唯一时保留候选。</p></details><details class="self-check"><summary>一个BER长度错误或计数跳变是否足以认定设备坏了？</summary><p>不足。应先确认抓包截断、丢帧、TCP重组、镜像/冗余重复、解码版本和配置差异。计数回绕或设备重启也可能改变序列；本模块只解释内置正常示例，不执行现场诊断。</p></details>''')

capacity_content=section('meaning','1. 先定义“信号”再谈数量','''<p>不存在适用于所有MMS、GOOSE、SV的一个固定“最少/最多信号数”。字段整数范围、ASN.1列表可编码范围、有效服务要求和设备允许配置是不同约束；“语法能编码空列表”不能推出“工程应发布零信号”。本模块使用非空数据集；不虚构一个跨协议的数值下限。</p>'''+table(['协议','这里的计数对象','最小/最大该怎样回答'],[('MMS','Read请求变量数、AccessResult项数；Report本次包含成员数及结构内叶子','依服务语义、协商PDU、列表/结构/分段与设备限制；没有一个固定全局信号上限/下限'),('GOOSE','numDatSetEntries是DataSet顶层成员数；allData一项可能是结构/数组','编码可表示的整数不等于可装入单Ethernet帧的成员数；有效发布与空DataSet支持按版本/设备核对'),('SV','每ASDU的配置成员、通道值/q对；noASDU是聚合组数','八通道非标准全局固定数；ASDU计数范围也不是信号数量上限；须核对配置文件/映射与实现')])+'''<p>本例GOOSE有2个标量FCDA（位置与品质），工程上描述1个位置反馈。SV有16个标量FCDA组成8通道，一帧含1个或2个ASDU；GOOSE中若把整个ST/FCD放成一个成员，内部stVal/q/t是多个叶子。DataSet成员数不能直接叫“业务测点数”。</p>''')
capacity_content+=section('constraints','2. 分开计算四层约束',table(['层面','MMS','GOOSE','SV'],[('理论/模型','变量/结构/命名列表、报告选择位图','FCDA粒度、类型展开与成员顺序','通道布局、值/q组合、ASDU与采样模式'),('协议/编码','ASN.1/BER开销、协商maxPdu、服务/报告分段','BER值类型、引用串、计数和长度阈值；固定头Length字段','外层BER、ASDU重复头、固定宽度seqData；Length字段'),('网络','TCP可分段重组，PDU通常可跨多个Ethernet帧；路径MTU影响分段','传统8-1单二层帧，不能套用IP分片；常见1500字节MAC客户数据预算','传统9-2单二层帧，帧预算与每秒帧率/链路占用需一起算'),('工程/实现','MICS/PIXIT/服务能力、PDU和变量列表限额、RCB限制','SCD与设备发布/订阅能力、时延、CPU、数据集与重传负荷','SCD nofASDU、配置文件、接收通道、采样频率、网络冗余与处理预算')])+'''<p>以常见未扩展Ethernet的1500字节MAC客户数据为例，它不是整帧含MAC/FCS的长度。单层VLAN增加MAC头开销，是否仍保留1500字节客户数据取决于实际链路能力；不能把1500随意减去14或18两次。MMS的“一个PDU”与“一个Ethernet帧”必须分开问，TCP分段不等于MMS应用报告分段。巨帧/多标签/安全扩展须另算，不是默认解决方案。</p>''')
capacity_content+=section('goose-budget','3. 可复算的 GOOSE 容量算例','''<p>限定为本例短引用、所有头字段及计数保持同样长度、无安全扩展，每成员均为Dbpos标量。每项编码84 02 06 xx占4字节。案例原allData两项合计9字节（Dbpos4+Quality5）。令h(L)=2，当L&lt;128；h(L)=3，当128≤L≤255；h(L)=4，当256≤L≤65535，它是本例单字节Tag加BER Length的头长。</p>'''+pre('N = 假设的Dbpos标量成员数\nB = gocbRef…numDatSetEntries这些头字段的总编码长度（numDatSetEntries需按N更新）\nD = 4 × N\nA = B + h(D) + D             # APDU Value长度\nGOOSE客户数据 = 8 + h(A) + A\n要求：8 + h(A) + A ≤ 本链路允许客户数据；还须满足设备/配置约束')+'''<p>实际生成的本例GOOSE帧见下表：帧长减14即客户数据长度。以N=100测试时，allData Value=400字节，h(D)=4；numDatSetEntries=100仍占1字节值，但到128必须增加整数编码字节。本例N=100时B=85，A=85+4+400=489，客户数据=8+4+489=501字节，低于声明的1500预算；这只是满足本算例长度条件，不证明设备支持100成员。不要将(1500−8)/4向下取整就当最大值：漏掉引用、计数、allData与外层BER头，还未核对装置能力。</p>'''+table(['可复算项','字节数'],[('本例GOOSE完整帧（无FCS）',BY_ID['goose-open']['size']),('本例GOOSE客户数据 = 帧长−14',BY_ID['goose-open']['size']-14),('本例GOOSE固定头',8),('本例GOOSE APDU',BY_ID['goose-open']['size']-22),('本例allData Value',9)]))
capacity_content+=section('sv-budget','4. SV 的具体网络预算','''<p>本例单ASDU中svID等固定字段编码共22字节，seqData是2字节Tag/Length+64字节值；ASDU Value=88，ASDU整体=90。一个ASDU时：seqASDU=2+90=92；noASDU=3；SavPdu Value=95、整体=97；再加8字节固定头，客户数据105；加14字节Ethernet头，帧为119字节（无FCS）。下面以构建结果为最终算术核对；若前文参数改动，必须同步重算。</p>'''+table(['构建的案例','无FCS帧长','MAC客户数据','其中seqData'],[('单ASDU',BY_ID['sv-one']['size'],BY_ID['sv-one']['size']-14,'64字节'),('两ASDU',BY_ID['sv-two']['size'],BY_ID['sv-two']['size']-14,'2×64字节')])+'''<p>在50Hz、每周波80样本、一个样本组/ASDU的声明下，单ASDU每秒4000帧，两ASDU可为每秒2000帧；这里只是理想聚合算术，不决定真实时延/发送节奏。估算线上占用还需加FCS4、前导码/SFD8、帧间隙12及适用VLAN/冗余开销。正确做法是按类型和实际配置精算，再查看设备文档的支持限额与工程预算；本站不提供通用推荐“合理信号数”。</p>''')
capacity_content+=section('mms-budget','5. MMS 不能从 MTU 得出服务信号上限','''<p>本例Read一个Dbpos的完整请求与响应长短不同：请求含变量名与访问规格，响应含结果值。按同样变量数量，字符串长度、结构/数组、可选字段、访问错误和BER长度阈值都会改变PDU。应先确认Initiate协商的最大MMS PDU、设备单次访问数量及报告/RCB限额，再按当前服务和实际编码计算。</p><p>TCP负责字节流分段/重组，因此一个MMS PDU可跨多帧；“最多多少信号”不能只用1500除以单值宽度。报告只选部分成员且可能应用分段，也不等于任意超大报告总能被对端支持。SCD声明、设备能力、当前运行时协商及具体服务结果需要共同查证。</p>''')

CONTENT={'packet-analysis':overview,'packet-mms':mms_content,'packet-goose':goose_content,'packet-sv':sv_content,'packet-scd-mapping':mapping_content,'packet-cases':cases_content,'packet-capacity':capacity_content}

def build():
    write(OUT/'data/packet-examples.js','/* Original fixed examples, generated by scripts/build_packet_lessons.py. */\nwindow.IEC61850_PACKET_EXAMPLES = '+json.dumps(CASES,ensure_ascii=False,indent=2)+';\n')
    write(OUT/'data/packet-demo-two-asdu.scd',(OUT/'data/packet-demo.scd').read_text(encoding='utf-8').replace('nofASDU="1"','nofASDU="2"'))
    for index,(stem,title) in enumerate(PAGES):
        continue_links='<p>'+''.join('<a href="'+s+'.html">'+t+'</a> · ' for s,t in PAGES if s!=stem)+'</p>'
        content=CONTENT[stem]+section('sources','来源、版次与适用范围',SOURCES)+section('continue','继续阅读',continue_links)
        write(OUT/'chapters'/f'{stem}.html','<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'｜IEC 61850 离线知识库</title><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/packet-lessons.css"></head><body><header class="top"><div class="chapter-nav"><a href="../index.html">返回首页</a> · <a href="packet-analysis.html">报文解析上级目录</a></div><div class="chapter"><h1>'+title+'</h1><p>配置 → 信号 → 编码 → 字段 → 工程证据</p></div></header><main class="chapter"><noscript><nav class="breadcrumb" aria-label="面包屑"><a href="../index.html">首页</a> → <a href="packet-analysis.html">报文解析</a></nav></noscript>'+BOUNDARY+content+'</main><footer class="foot">原创教学材料 · <a href="packet-analysis.html">报文解析总览</a> · <a href="../index.html">首页术语搜索</a></footer><script src="../assets/navigation.js"></script><script src="../data/packet-examples.js"></script><script src="../assets/packet-lessons.js"></script></body></html>\n')
    # One shared catalog; move the existing overview out of protocol without duplicating it.
    nav=OUT/'assets/navigation.js';text=nav.read_text(encoding='utf-8')
    match=re.search(r'const groups = (\[.*?\]);',text,re.S);groups=json.loads(match.group(1))
    groups=[g for g in groups if g['id']!='packets']
    for g in groups:g['items']=[it for it in g['items'] if it[0]!='packet-analysis.html']
    group=dict(id='packets',label='报文解析',entry='packet-analysis.html',items=[[s+'.html',t,'入门与三类报文' if i<4 else '配置、案例与约束'] for i,(s,t) in enumerate(PAGES)])
    groups.insert(next(i for i,g in enumerate(groups) if g['id']=='protocol')+1,group)
    text=text[:match.start(1)]+json.dumps(groups,ensure_ascii=False,indent=2)+text[match.end(1):]
    old="'packet-analysis','developer-data-contracts'"
    new="'packet-analysis','packet-mms','packet-goose','packet-sv','packet-scd-mapping','packet-cases','packet-capacity','developer-data-contracts'"
    text=text.replace(old,new);write(nav,text)
    home=OUT/'index.html';text=home.read_text(encoding='utf-8')
    card='<section class="card" id="packet-lessons-entry"><p class="section-kicker">报文解析 · 离线交互教学</p><h2>把 SCD、信号和 Hex 连起来</h2><p><a href="chapters/packet-analysis.html"><b>进入报文解析总览 →</b></a></p><p><a href="chapters/packet-mms.html">MMS 请求与响应</a> · <a href="chapters/packet-goose.html">GOOSE 状态变化</a> · <a href="chapters/packet-sv.html">SV 八通道采样</a> · <a href="chapters/packet-scd-mapping.html">SCD 双向映射</a> · <a href="chapters/packet-cases.html">完整案例</a> · <a href="chapters/packet-capacity.html">信号数量</a></p><p>内置原创完整数据帧，点击字段与Hex联动；不依赖网络或抓包导入。</p></section>'
    text=re.sub(r'<section class="card" id="packet-lessons-entry">.*?</section>\s*','',text,flags=re.S)
    text=text.replace('<section class="card" id="reference">',card+'\n<section class="card" id="reference">')
    text=text.replace('静态协议字段阅读','报文解析教学').replace('>静态协议字段</a>','>报文解析总览</a>')
    tag='<script src="data/packet-terms.js"></script>'
    if tag not in text:text=text.replace('<script src="assets/app.js">',tag+'<script src="assets/app.js">')
    write(home,text)
    file=OUT/'assets/home.js';text=file.read_text(encoding='utf-8')
    if 'href="#packet-lessons-entry"' not in text:text=text.replace('<li><a href="#reference">','<li><a href="#packet-lessons-entry">报文解析教学</a></li><li><a href="#reference">')
    write(file,text)
    terms=[]
    for i,(stem,title) in enumerate(PAGES):
        aliases=[['报文解析','Hex','Wireshark','BER','TLV'],['MMS','Read Request','Read Response','InvokeID','Service','VariableAccessSpecification','AccessResult','GetNameList'],['GOOSE','allData','gocbRef','stNum','sqNum','Dbpos','GoCB'],['SV','SMV','ASDU','svID','smpCnt','smpSynch','seqData'],['SCD报文映射','APPID','GSEControl','SampledValueControl'],['实际报文案例','状态变化','断路器合位'],['信号数量','MTU','报文容量','最多几个信号']][i]
        terms.append(dict(id='packet-lesson-'+str(i),zh=title,en=aliases[0],aliases=aliases,category='报文解析教学',level='报文解析 → '+title,summary=['三类核心通信与标准体系、前置知识和Hex阅读法','完整MMS单变量Read请求/响应，解释服务选择与Dbpos','数据集到二层GOOSE，事件首帧/重传的字段变化','八通道16个FCDA、样本与品质、单/多ASDU','实例和类型、DataSet、控制块与网络字段双向核对','内置完整Hex与可展开答案，区分事实、配置和未知','分层约束与容量演算，不虚构固定最大信号数'][i],href='chapters/'+stem+'.html#'+['scope','hex','hex','hex','forward','cases','meaning'][i],related=[]))
    write(OUT/'data/packet-terms.js','(function(){const terms=window.IEC61850_TERMS;for(const t of '+json.dumps(terms,ensure_ascii=False,indent=2)+'){const i=terms.findIndex(x=>x.id===t.id);if(i<0)terms.push(t);else terms[i]=t;}}());\n')
    for stem in ['communication-process','service-mapping','control-blocks-reference','object-reference','scd-reading-toolbox','abbreviation-index','learning-path']:
        file=OUT/'chapters'/f'{stem}.html';text=file.read_text(encoding='utf-8')
        text=re.sub(r'<section><h2 id="packet-lessons-related">.*?</section>','',text,flags=re.S)
        text=text.replace('</main>',section('packet-lessons-related','报文解析：配置与 Hex 联读','<p><a href="packet-analysis.html">三类核心通信与前置知识</a> · <a href="packet-scd-mapping.html">SCD到报文的双向映射</a> · <a href="packet-cases.html">完整MMS / GOOSE / SV案例</a>。沿模型、数据集、控制块和编码追踪同一信号。</p>')+'</main>')
        write(file,text)
    print(json.dumps(dict(pages=len(PAGES),examples=len(CASES),sizes={c['id']:c['size'] for c in CASES}),ensure_ascii=False))

if __name__=='__main__':build()
